import{_ as o,l as i,o as e,c as n,v as l,p as s,x as t,d as c,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"Hall 随机游走","description":"","frontmatter":{"title":"Hall 随机游走","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/hall-random-walk.md","filePath":"econ/hall-random-walk.md","lastUpdated":1789023840000}'),d={name:"econ/hall-random-walk.md"};function _(E,a,m,b,u,B){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="hall-随机游走" tabindex="-1">Hall 随机游走 <a class="header-anchor" href="#hall-随机游走" aria-label="Permalink to &quot;Hall 随机游走&quot;">​</a></h1><div class="epigraph"><p>欧拉加上理性预期，可预测的收入就不应该预测消费的变化；消费本身近似随机游走。</p><footer>—— Hall, Stochastic Implications of the Life Cycle–Permanent Income Hypothesis, JPE 1978</footer></div><p><a href="/econ/consumption-euler">上一课</a>已经把 IS 的 \\(C(Y)\\) 换成欧拉，并预告 Hall：若 \\(r\\) 与偏好使折现后边际效用成为鞅，则消费近似随机游走。本课的缺口就是把这条<strong>可观测含义</strong>写清：从欧拉到随机游走要哪些额外假设，以及过度敏感/过度平滑为何是对随机游走的偏离而不是把 \\(C(Y)\\) 请回当理论。新凯恩斯下一课给价格粘性；本课仍在消费侧。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欧拉 \\(u&#39;(c_t)=\\beta\\mathbb{E}_t\\bigl[(1+r_t)u&#39;(c_{t+1})\\bigr]\\) 是一阶条件，还不是「\\(\\Delta c\\) 不可预测」。Hall（1978）的缺口是：在理性预期、常实际利率、二次效用（或线性化后的常 \\(\\sigma\\)）下，边际效用从而消费成为鞅，</p> \\[c_{t+1}=c_t+\\varepsilon_{t+1},\\qquad \\mathbb{E}_t\\varepsilon_{t+1}=0. \\]<p>于是滞后收入、滞后股票价格等已知信息不应预测 \\(\\Delta c_{t+1}\\)。这与 Keynes 的同期边际消费倾向冲突：可预测的 \\(Y\\) 波动应被资本市场抹平。本课不重推欧拉，只把随机游走从欧拉里读出来。</p><p><span class="marginnote">随机游走是检验，不是对所有样本的描述。利率变动、偏好冲击、流动性约束都会留下可预测成分。拒绝随机游走不等于欧拉在结构上不成立。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>二次效用使 \\(u&#39;\\) 线性，常 \\(r\\) 使折现因子为常数，理性预期把条件期望变成鞅。对数效用加对数正态近似，得到 \\(\\mathbb{E}_t\\Delta\\ln c_{t+1}\\) 由 \\(r-\\rho\\) 决定；若 \\(r\\) 恒定，则 \\(\\Delta\\ln c\\) 仍不可被其他已知变量预测。检验：把 \\(\\Delta c_{t+1}\\) 对滞后期 \\(Y\\)、滞后期 \\(c\\) 以外的工具回归，系数应为零。</p>',10)),(e(),s(h,null,{default:t(()=>[p(r,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20EU%5B%22%E6%AC%A7%E6%8B%89%22%5D%20--%3E%20RE%5B%22%E7%90%86%E6%80%A7%E9%A2%84%E6%9C%9F%22%5D%0A%20%20QUAD%5B%22%E4%BA%8C%E6%AC%A1%E6%95%88%E7%94%A8%E4%B8%8E%E5%B8%B8%20r%22%5D%20--%3E%20RW%5B%22%E6%B6%88%E8%B4%B9%E8%BF%91%E9%9A%8F%E6%9C%BA%E6%B8%B8%E8%B5%B0%22%5D%0A%20%20RE%20--%3E%20RW%0A%20%20RW%20--%3E%20TEST%5B%22%E5%8F%AF%E9%A2%84%E6%B5%8B%E6%94%B6%E5%85%A5%E4%B8%8D%E9%A2%84%E6%B5%8B%20%CE%94c%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<p>持久收入：只有未预期的持久资源变化才移动 \\(c\\) 的水平；之后 \\(\\Delta c\\) 仍是噪声。暂时收入若能借贷，消费几乎不动。这把 Hall 接到 Friedman 持久收入，而不是接到静态 \\(C=cY\\)。</p><h3 id="利率不是永远恒定" tabindex="-1">利率不是永远恒定 <a class="header-anchor" href="#利率不是永远恒定" aria-label="Permalink to &quot;利率不是永远恒定&quot;">​</a></h3><p>上一课的线性欧拉是 \\(\\mathbb{E}_t\\Delta c_{t+1}=\\sigma(r_t-\\rho)\\)。\\(r\\) 可预测时，\\(\\Delta c\\) 也可预测——随机游走被「消费对利率的反应」修正，不是理论失败。新凯恩斯 IS 正是保留这一项，让名义政策通过实际利率移动 \\(\\mathbb{E}\\Delta c\\)。Hall 的严格随机游走是 \\(r\\) 被当作常数的极限。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>家庭用资产抹平可预见的收入起伏。信息集里已经有的 \\(Y_{t+1}\\) 预测，不应再改变 \\(c_{t+1}-c_t\\)。新信息（持久收入修订）进入 \\(\\varepsilon_{t+1}\\)，消费水平跳一次。流动性约束把欧拉变成不等式：受约束家庭的 \\(\\Delta c\\) 跟着当期收入，可预测性回来，短期乘数变大。习惯形成使 \\(\\Delta c\\) 出现惯性。过度敏感（对可预测收入反应过大）与过度平滑（对持久冲击反应不足）是经验偏离的两个方向。</p><p>资产定价用同一欧拉接随机折现因子；股票溢价之谜不在本课展开。宏观主干只保留：可预测收入不是 Keynes 意义上的消费驱动器，除非声明摩擦。</p><p>检验上，工具变量必须在信息集内：滞后收入、滞后消费（在随机游走下滞后 \\(c\\) 不应预测 \\(\\Delta c\\)，除了测量误差）。发现可预测性，下一步是问哪条假设坏了——\\(r\\) 变动、约束、习惯、偏好冲击——而不是回到 \\(C=cY\\)。过度平滑相对持久收入假说：消费对可识别的持久冲击反应小于财富效应所要求的，可能是保险不完全，也可能是习惯。本课列清单，不估系数。</p><p>新凯恩斯把 Hall 的极限放开：政策利率进入 \\(\\mathbb{E}\\Delta c\\)，消费有可预测成分，但那是对 \\(r\\) 的反应，仍不是对可预测劳动收入的 Keynes 反应。两种可预测性不要混。</p><p><span class="marginnote">Hall 自己也报告过滞后股票价格对消费的预测力等偏离。本课把随机游走当基准含义，把偏离当摩擦清单，不把 \\(C(Y)\\) 请回当结构。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计 \\(\\sigma\\)，不把微观面板的完整消费保险文献搬进来。公司金融的证券结构不是单一债券。量化栏的价格发现不是 \\(\\varepsilon_{t+1}\\)。随机游走也不否定商品市场均衡：投资仍可剧烈波动，IS 仍要有交点，只是消费核换成前瞻欧拉。</p><p>后课默认：消费的可预测收入通道在完全市场下应接近零；政策利率通过 \\(r\\) 进入 \\(\\mathbb{E}\\Delta c\\)。下一课给名义刚性，让名义 \\(i\\) 能暂时支配这个 \\(r\\)。确定性 Ramsey 欧拉是本式无期望的版本，与 RCK 同一条一阶条件，本课不重推。流动性约束使检验拒绝随机游走时，应声明是摩擦，不是把 IS 的 \\(C(Y)\\) 请回。</p><p>股票溢价与 SDF 检验留给资产定价，宏观主干只留无风险欧拉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>欧拉是结构；Hall 是欧拉加理性预期、常 \\(r\\)、二次（或线性）效用后的含义。</li><li>可预测收入不应预测 \\(\\Delta c\\)；消费水平只对新闻跳。</li><li>\\(r\\) 可预测时，\\(\\Delta c\\) 也可预测——那是 NK 的利率通道，不是把 \\(C(Y)\\) 请回。</li><li>流动性约束与习惯解释过度敏感与惯性。</li><li>出处：Hall, JPE 1978；欧拉见上一课与 Ramsey。</li></ul>',15))])}const f=o(d,[["render",_]]);export{A as __pageData,f as default};
